def write_md(filename, title, meta, body):
    filepath = os.path.join(OUT_DIR, f"{filename}.md")
    content = f"# {title}\n\n"
    for k, v in meta.items():
        if v:
            content += f"{k}: {v}\n"
    content += f"\n{body}\n"
    with open(filepath, "w", encoding="utf-8") as f:
        f.write(content)

function normalizeSlug(str: string): string {
  return str
    .toLowerCase()
    .replace(/^(post_index|post_|project_)/, '')
    .replace(/-[a-f0-9]{8,16}$/, '')
    .replace(/-\d+$/, '')
    .replace(/_/g, '-')
    .trim();
}

function relatedPostSlugs(slug: string, articles: IndexEntry[]): IndexEntry[] {
  const relationMap = relatedPosts as Record<string, string[]>;
  const cleanCurrentSlug = normalizeSlug(slug);
  const matchedKey = Object.keys(relationMap).find(key => normalizeSlug(key) === cleanCurrentSlug);
  if (!matchedKey) return [];
  return relationMap[matchedKey]
    .map(relSlug => articles.find(a => normalizeSlug(a.slug) === normalizeSlug(relSlug)))
    .filter((a): a is IndexEntry => Boolean(a));
}
